import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.DXGs2oJ2.js";const g=JSON.parse('{"title":"阅读导引","description":"","frontmatter":{},"headers":[],"relativePath":"00-preface/阅读导引.md","filePath":"00-preface/阅读导引.md","lastUpdated":1793361704000}'),o={name:"00-preface/阅读导引.md"};function l(n,t,i,s,h,p){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="阅读导引" tabindex="-1">阅读导引 <a class="header-anchor" href="#阅读导引" aria-label="Permalink to &quot;阅读导引&quot;">​</a></h1><h2 id="一、写作背景" tabindex="-1">一、写作背景 <a class="header-anchor" href="#一、写作背景" aria-label="Permalink to &quot;一、写作背景&quot;">​</a></h2><p>2026 年 5 月，一篇被 ACL 2026 Findings 收录的综述把 LLM Agent 的记忆机制演进形式化为三个阶段：<strong>存储</strong>（trajectory preservation，保存轨迹）、<strong>反思</strong>（trajectory refinement，精炼轨迹）、<strong>体验</strong>（trajectory abstraction，抽象轨迹）。这个划分的价值不在于给技术分代，而在于它指出了一件工程上很麻烦的事：三个阶段对应三套完全不同的正确性标准。存储阶段要求「不丢」，反思阶段要求「不错」，体验阶段要求「可迁移」。用同一套机制去满足三种标准，是当前多数记忆系统在规模化时失效的根因。</p><p>同一时期，工程侧出现了一次值得记录的收敛。以「单遍 ADD-only 提取 + 多信号检索 + 时序推理 + 记忆衰减」为核心的写入与召回范式，被多家主要实现独立采纳。这说明「不覆盖已有事实」这个下限已经成为共识——一次糟糕的提取最多引入噪声，永远不会摧毁一条真实事实。但收敛也带来一个新的问题：当基础范式趋同时，差异化转移到更难的地方——冲突如何裁决、删除如何证明、成本如何可控、经验如何抽象。</p><p>本手册以此为出发点。它不试图给出一套放之四海皆准的方案，而是围绕一个具体问题组织：</p><blockquote><p><strong>在 2026 年的技术条件下，一个企业或一个开发者，应该如何在记忆的写入、检索、遗忘、审计与演化之间做出可辩护的取舍？</strong></p></blockquote><p>「可辩护」是关键词。它意味着每一个技术选择都要能回答：为什么不是另一个、代价是什么、在什么条件下会失效。一个无法被追问的选择，不构成工程决策。</p><h2 id="二、目标读者与收获" tabindex="-1">二、目标读者与收获 <a class="header-anchor" href="#二、目标读者与收获" aria-label="Permalink to &quot;二、目标读者与收获&quot;">​</a></h2><p>本手册面向需要为 AI 系统设计、建设、运行或审计记忆能力的人。</p><table tabindex="0"><thead><tr><th>读者</th><th>建议关注</th><th>你将获得</th></tr></thead><tbody><tr><td>Agent / AI 应用开发者</td><td>构建篇、接入章节</td><td>掌握单遍写入、冲突消解、多信号检索、渐进式披露的工程方法</td></tr><tr><td>架构师与平台工程师</td><td>架构篇、运行篇</td><td>建立从存储引擎到治理底座的完整视图，理解本地优先与托管服务的真实代价</td></tr><tr><td>技术负责人与研发管理者</td><td>架构篇、实践篇、调优篇</td><td>判断记忆系统的成熟度、选型边界与生产准入条件，支撑立项与采购</td></tr><tr><td>产品与业务负责人</td><td>架构篇、典型场景、展望篇</td><td>理解不同画像对记忆的期待与恐惧，以及从「记住」走向「被信任」的产品条件</td></tr><tr><td>安全、合规与运维人员</td><td>治理篇、运行篇</td><td>建立哈希链审计、级联删除、脱敏写入与完整性验证的实操机制</td></tr><tr><td>研究者与生态贡献者</td><td>调优篇、展望篇</td><td>了解工业界的一线约束、基准的方法学争议与未解问题</td></tr></tbody></table><p>完整阅读后，你将能够：</p><ul><li>判断一个场景的记忆需求属于哪一级成熟度，据此决定投入边界；</li><li>区分「尽力而为」与「强保证」两类机制，不被过度承诺误导；</li><li>设计可被脚本验证的审计、删除与隔离方案，而不是依赖流程与人工；</li><li>读懂基准分数背后的方法学差异，知道哪些数字可以比较、哪些不能；</li><li>为记忆系统建立从 Trace 到 Badcase 再到受控发布的改进闭环。</li></ul><h2 id="三、篇章结构" tabindex="-1">三、篇章结构 <a class="header-anchor" href="#三、篇章结构" aria-label="Permalink to &quot;三、篇章结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>篇章</th><th>章节范围</th><th>核心内容</th></tr></thead><tbody><tr><td>卷首</td><td>技术观察</td><td>基于公开可复现信号，观察 2026 年记忆系统的技术收敛与能力落差</td></tr><tr><td>架构篇</td><td>第 1–3 章</td><td>记忆为何是一等原语、参考架构的责任域划分、L1–L4 成熟度分级</td></tr><tr><td>构建篇</td><td>第 4–7 章</td><td>写入范式、存储与压缩、检索融合与预算控制、MCP 与框架接入</td></tr><tr><td>运行篇</td><td>第 8–11 章</td><td>部署形态、状态恢复与一致性、多用户作用域治理、规模化运营</td></tr><tr><td>治理篇</td><td>第 12–15 章</td><td>可审计性、删除的四层语义、写入前安全、合规与数据主权</td></tr><tr><td>调优篇</td><td>第 16–19 章</td><td>可复现基准、评测陷阱、质量度量与 Badcase 闭环、受控自进化</td></tr><tr><td>实践篇</td><td>第 20–22 章</td><td>第一梯队系统对照、选型与迁移路径、典型场景实践</td></tr><tr><td>展望篇</td><td>第 23 章</td><td>五个未解问题与 2027 路线图</td></tr></tbody></table><h2 id="四、章节导航" tabindex="-1">四、章节导航 <a class="header-anchor" href="#四、章节导航" aria-label="Permalink to &quot;四、章节导航&quot;">​</a></h2><table tabindex="0"><thead><tr><th>篇章</th><th>章节</th><th>核心内容</th></tr></thead><tbody><tr><td>架构篇</td><td>第 1 章　记忆为什么成为一等原语</td><td>四种失效形态、三重身份、三对根本矛盾、能力边界</td></tr><tr><td>架构篇</td><td>第 2 章　记忆系统参考架构</td><td>五域责任划分、保证强度分层、生命周期闭环</td></tr><tr><td>架构篇</td><td>第 3 章　形态与成熟度：L1–L4 分级</td><td>责任与可验证两轴、每级架构与失效、升级信号</td></tr><tr><td>构建篇</td><td>第 4 章　写入：抽取、分型与冲突消解</td><td>单遍 ADD-only、双时间轴、六类冲突与四操作、多模态不丢弃</td></tr><tr><td>构建篇</td><td>第 5 章　存储：分层、作用域与无损压缩</td><td>物理隔离、SQLite 边界、热温冷分层、AIC 压缩</td></tr><tr><td>构建篇</td><td>第 6 章　检索：多信号融合与预算控制</td><td>五路信号、相关性下限、渐进式披露、预算感知</td></tr><tr><td>构建篇</td><td>第 7 章　接入：MCP、API 与框架适配</td><td>55 条工具面的设计取舍、REST 路由、组件生态、切换成本</td></tr><tr><td>运行篇</td><td>第 8 章　部署形态：本地优先的真实边界</td><td>零依赖的四个后果与代价、四种部署形态、自托管与 SaaS</td></tr><tr><td>运行篇</td><td>第 9 章　状态恢复、异步与一致性</td><td>同步与异步写入、flush 屏障、幂等与恢复演练</td></tr><tr><td>运行篇</td><td>第 10 章　多用户与多 Agent 的作用域治理</td><td>四维作用域、物理与逻辑隔离、共享记忆的未解问题</td></tr><tr><td>运行篇</td><td>第 11 章　规模化运营：成本、延迟与容量</td><td>四项成本结构、容量估算、运营指标</td></tr><tr><td>治理篇</td><td>第 12 章　可审计性：哈希链、来源追溯与证据链</td><td>哈希链实现、审计覆盖面、指针链回溯、证明边界</td></tr><tr><td>治理篇</td><td>第 13 章　删除与遗忘的四层语义</td><td>四层删除、dry_run、掩码取舍、删除可验证性难题</td></tr><tr><td>治理篇</td><td>第 14 章　写入前安全：公证、注入与凭据防护</td><td>三项写入前检查、敏感度分级、记忆投毒</td></tr><tr><td>治理篇</td><td>第 15 章　合规与数据主权</td><td>数据驻留、导出与迁移、隔离、定价与门控边界</td></tr><tr><td>调优篇</td><td>第 16 章　基准：可复现的方法学</td><td>三层可信度、基准五要素、三条红线、诚实交代</td></tr><tr><td>调优篇</td><td>第 17 章　基准争议与评测陷阱</td><td>不可比的原因、30% 下降的含义、五个常见陷阱</td></tr><tr><td>调优篇</td><td>第 18 章　记忆质量度量与 Badcase 闭环</td><td>六维质量、召回健康度、诚实度量、四步闭环</td></tr><tr><td>调优篇</td><td>第 19 章　受控自进化：从存储到体验</td><td>三阶段框架、经验前置条件、负迁移、回流约束</td></tr><tr><td>实践篇</td><td>第 20 章　第一梯队系统深度对照</td><td>定位、能力矩阵、范式收敛、检索粒度路线</td></tr><tr><td>实践篇</td><td>第 21 章　选型决策与迁移路径</td><td>五个前置问题、决策树、三条迁移路径、验收清单</td></tr><tr><td>实践篇</td><td>第 22 章　典型场景实践</td><td>五类场景的约束、设计、失效点与验收</td></tr><tr><td>展望篇</td><td>第 23 章　未解问题与 2027 路线图</td><td>五个未解问题、路线图表、五类角色行动建议</td></tr></tbody></table><h2 id="五、推荐阅读路径" tabindex="-1">五、推荐阅读路径 <a class="header-anchor" href="#五、推荐阅读路径" aria-label="Permalink to &quot;五、推荐阅读路径&quot;">​</a></h2><ul><li><strong>第一次系统了解 AI 记忆</strong>：技术观察 → 第 1 章 → 第 2 章 → 第 4–6 章 → 第 20 章</li><li><strong>正在把记忆接入生产</strong>：第 8–11 章 → 第 12–14 章 → 第 16–18 章</li><li><strong>负责选型或立项</strong>：技术观察 → 第 1 章 → 第 3 章 → 第 20–21 章 → 第 23 章</li><li><strong>负责合规与审计</strong>：第 12–15 章 → 第 18 章 → 第 22 章第 4 节</li><li><strong>关注前沿与研究方向</strong>：第 1 章 → 第 16–19 章 → 第 23 章</li></ul><h2 id="六、关于本书的数据与事实" tabindex="-1">六、关于本书的数据与事实 <a class="header-anchor" href="#六、关于本书的数据与事实" aria-label="Permalink to &quot;六、关于本书的数据与事实&quot;">​</a></h2><p>本书对事实的处理遵循三条规则，请读者据此判断可信度。</p><p><strong>第一，所有数字都标注口径与时间。</strong> 基准分数标注数据集版本、judge 类型与是否完整运行；价格标注币种与生效时间；论文标注 arXiv 编号。没有口径的数字不出现。</p><p><strong>第二，无法核验的论断一律删除，而不是弱化表述。</strong> 本书不写「据传」「业内普遍认为」这类无法追溯来源的判断。少数必须提及但证据不足的内容，会明确写出「截至 2026 年 10 月的公开文档中未见说明」。</p><p><strong>第三，对自家实现与对竞品采用同一套审慎标准。</strong> 书中对 Mnemosyne OS 的描述同样标注边界与代价，包括其基准分数尚未由仓库内一次完整运行独立复算这一事实（见第 16 章）。对竞品的描述只写其边界，不写其弱点。</p><p>读者若发现任何数字与本手册所述口径不符，应当以原始来源为准。附录 B 给出全部可复现资源的入口。</p><h2 id="七、下一步规划" tabindex="-1">七、下一步规划 <a class="header-anchor" href="#七、下一步规划" aria-label="Permalink to &quot;七、下一步规划&quot;">​</a></h2><p>本手册将以持续修订的方式维护，而不是在首次发布后封存。接下来的重点包括：</p><ul><li><strong>补齐基准的完整复算</strong>：把当前仅有骨架的基准仓库推进到「任意第三方可一条命令复算出 headline 分数」的状态，并公开每次运行的机器可读记录。</li><li><strong>扩展中文与非英语场景</strong>：现有主流基准以英语为中心，中文的专有名词、时间表达、近义表达在纯嵌入召回下失准明显，需要独立的对照实验与数据集。</li><li><strong>深化删除可验证性</strong>：尝试给出一种可跨系统交换的删除审计格式，使「已彻底清除」从口头承诺变为可验证事实。</li><li><strong>补充跨 Agent 共享的权限模型</strong>：把「共享读」与「共享写」分开设计，先解决读侧的一致性，再讨论写侧的仲裁。</li><li><strong>跟进产品形态变化</strong>：记忆系统的边界正在与运行时、上下文层、Skill 体系融合，需要持续修正已经不再适用的判断。</li></ul><p>欢迎通过 Issue 或 Pull Request 指出事实错误、概念歧义与需要补充的主题。涉及企业数据与内部系统时，请先完成必要的脱敏与许可确认。</p><hr>',29)])])}const u=d(o,[["render",l]]);export{g as __pageData,u as default};
